USE kolmogorov;

PRAGMA yt.PoolTrees = 'physical,cloud_default';
PRAGMA yt.StaticPool = 'selfdriving-robot-planning';

import onnx


def parse_tensors(scene_tensors: list[dict]) -> dict:
    out = {}
    for x in scene_tensors:
        tensor = onnx.helper.TensorProto()
        tensor.ParseFromString(yt.yson.get_bytes(x["value"]))
        out[x["key"]] = onnx.numpy_helper.to_array(tensor)
    return out
